+body{
+  background-color:aliceblue;
+}
+:root {
+  /* fonts */
+  --font-poppins: Roboto;
+  --font-freehand: Freehand;
+}
+
+
+
+/* HOME */
+ svg {
+  margin-top: 150px;
+  font-family: 'Russo One', sans-serif;
+  border-radius: 6px;
+  position: relative;
+  display:flex;
+   justify-content:center; 
+}
+
+.name1 {
+  font-size: 300px; 
+  animation: stroke 5s infinite alternate;
+  stroke-width: 2;
+  stroke: white;
+}
+@keyframes stroke {
+  0%   {
+    fill: #0c2461; stroke: white;
+    stroke-dashoffset: 25%; stroke-dasharray: 0 50%; stroke-width:10;
+  }
+  70%  {fill: #0c2461; stroke:white; }
+  80%  {fill: #0c2461; stroke: white; stroke-width: 8; }
+  100% {
+    fill: white; stroke: #0c2461; 
+    stroke-dashoffset: -25%; stroke-dasharray: 50% 0; stroke-width: 0;
+  }
+}
+
+
+
+/* About */
+.about-container{
+  display:flex;
+  margin-top: 20px;
+  margin-bottom: 200px;
+}
+.details{
+  margin-left: 100px;
+}
+.info-msg{
+font-family:monospac; 
+ color:#0c2461; 
+  text-align:center;
+  font-size: 29px;
+  max-width: 1000px;
+  padding-top: 70px;
+  padding-left: 100px;
+}
+.info-img{
+  width: 350px;
+  height:400px;
+   border-radius:100px;
+  margin-right: 100px;
+  margin-top: 10px;
+}
+
+.btn{
+  margin-top: 10px;
+  background-color:#0c2461; 
+  border-radius:88px;
+   font-size:30px; 
+   color:white;
+    width:350px;
+    height: 60px;
+}
+.btn:hover{
+  background-color:#6275e4;
+}
+
+
+
+
+
+
+/* EDU */
+.edu{
+  color:#f5f5f5;
+ background-color:#0c2461;
+   border-color: white;
+   border-radius: 30px;
+   border-style: solid;
+   border-width: 3px;
+   width:350px;
+   height: 350px;
+ padding-left: 20px;
+ text-decoration: none;
+}
+.edu:active{
+background-color:#6275e4;
+}
+.edu-div{
+ display: flex;
+ justify-content: space-between;
+ margin-top: 15px;
+ margin-bottom: 200px;
+}
+.title-edu{
+  color:#0c2461;
+  padding-left:405px;
+   padding-bottom:30px;
+    padding-top:40px;
+}
+.contact{
+  margin-bottom:3em;
+  margin-top:-15em
+}
+
+
+
+
+
+/* WORK */
+ /* General Work Section Styles */
+.edu-div {
+  display: flex;
+  flex-wrap: wrap;
+  justify-content: center;
+  gap: 20px;
+  margin-top: 20px;
+}
+.work {
+  text-decoration: none;
+  text-align: center;
+  margin-top: 50px;
+  width: 300px;
+}
+.work:active {
+  background-color: #6275e4;
+}
+.work-img {
+  width: 250px;
+  border-radius: 50%;
+  margin-bottom: 15px;
+}
+.work-description {
+  font-size: 18px;
+  max-width: 300px;
+  color: #0c2461;
+  font-family: 'Roboto', sans-serif;
+  margin: 0 auto;
+}
+.title-work {
+  color: #0c2461;
+  text-align: center;
+  margin-top: 10px;
+}
+
+
+
+
+
+
+
+@media screen and (max-width: 600px) { /* Adjust breakpoint as needed for phones */
+  svg{
+    padding: 120px 0 120px 0;
+    display: block;
+  }
+ .name1 {
+   font-size: 520px; 
+ }
+ 
+  .nav-a{
+    margin: 0 auto 30px; 
+  }
+
+  .home-container {
+    flex-direction: column; /* Reverse flex direction for phones */
+  }
+  .about-container{
+   flex-direction:column-reverse;
+   align-items: center;
+  }
+  
+  .info-msg {
+    font-size: 35px;
+    width: 330px;
+    letter-spacing: 1.5px;
+    word-spacing: 3px;
+    line-height: 1.3;
+    padding: 50px 0 50px 0;
+    text-align:unset;
+  }
+  .equal-width::after {
+    content: '';
+    display: inline-block;
+    width: 100%; /* Fill remaining space */
+}
+  .info-img {
+    width: 250px; /* Adjust max-width for phones */
+    border-radius: 100%;
+    height: 300px;
+    margin: 50px auto 15px; 
+    display: block; 
+  }
+  .btn{
+    background-color:#0c2461;                                                                                                             border-radius:88px;
+     font-size:20px; 
+     color:white;
+      width:200px;
+      height:50px;
+      max-width: 600px;
+      padding-left:0px;
+      margin: 0 auto 0 auto;
+    display: block; 
+  }
+  .details{ 
+margin-left: 10px;
+  } 
+  .edu-div{
+flex-direction: column;
+  }
+  .title-edu{
+    color:#0c2461;
+    padding-left:20px;
+      padding-top:90px;
+      text-decoration: underline;
+  }
+  .edu{
+    color:#f5f5f5;
+   background-color:#0c2461;
+     border-color: #74F38F;
+     border-radius: 30px;
+     border-style: solid;
+     border-width: 6px;
+     width:280px;
+     height: 300px;
+     margin: 0 auto 80px auto;
+  }
+  .title-work{
+    color:#0c2461;
+ padding-left: 0px;
+ text-align: center;
+      padding-top:90px;
+      text-decoration: underline;
+  }
+  .work{
+    margin-bottom: 50px;
+  }
+  
+
+.title-contact{
+  color:#0c2461;
+    padding-top:70px;
+    text-decoration: underline;
+    padding-bottom:0px;
+}
+
+.about-container{
+  margin-bottom: 50px;
+}
+.edu-div{
+  margin-bottom: 50px; 
+}
+.contact{
+  margin-bottom:3em;
+  margin-top:-15em
+}
+
+}
+
+
+
+
+@keyframes slide {
+  0% {
+    left: 0;
+    top: 0;
+  }
+  50% {
+    left: 750px;
+    top: 550px;
+  }
+  100% {
+    left: 750px;
+    top: 0;
+  }
+}
+.stage {
+  border-radius: 6px;
+  position: relative;
+}
+.stage .ball {
+   animation: slide 2s ease-in-out alternate;
+}
+
+.ball {
+  background:#0c2461;
+  border-radius: 50%;
+  height: 35px;
+  position: absolute;
+  width: 35px;
+  margin-left:17.5px;
+  border-width: 5px;
+  border-style: solid;
+  border-color: white;
+  margin-top: 21px;
+}
+
+
+.nav-a{
+  text-decoration:none;
+  color: #0c2461;
+  font-size: 45px;
+  border-style: solid;
+  border-width: 3px;
+  border-radius: 100%;
+  max-width: 55px;  
+  display: flex;
+  justify-content: center;
+  margin-top: -20px;
+  margin-bottom: 10px;
+}
+.nav-a:hover{
+  color: white;
+}
